import{_ as l,l as r,o as i,c as s,v as e,p as n,x as t,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"离散选择 logit / probit","description":"","frontmatter":{"title":"离散选择 logit / probit","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/discrete-choice.md","filePath":"econ/discrete-choice.md","lastUpdated":1789023840000}'),B={name:"econ/discrete-choice.md"};function h(E,a,_,A,m,u){const o=r("Mermaid");return i(),s("div",null,[a[1]||(a[1]=e('<h1 id="离散选择-logit-probit" tabindex="-1">离散选择 logit / probit <a class="header-anchor" href="#离散选择-logit-probit" aria-label="Permalink to &quot;离散选择 logit / probit&quot;">​</a></h1><div class="epigraph"><p>选项是离散的，观测到的是谁被选中；把选择写成效用比较加极值误差，份额就变成 logit，弹性才有从效用参数到反事实份额的通道。</p><footer>—— McFadden, Conditional Logit Analysis of Qualitative Choice Behavior, 1974；Train, Discrete Choice Methods with Simulation</footer></div><p><a href="/econ/structural-vs-reduced">上一课</a>划分了支撑内设计与支撑外结构。本课给出最小结构：离散选择。BLP 下一课把 logit 放进差异产品与价格内生；本课先钉条件 logit / probit 的识别与 IIA。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>通勤方式、买哪一品牌、是否劳动参与：\\(Y\\in\\{1,\\ldots,J\\}\\)。线性概率模型可以估，但概率可出 \\([0,1]\\)，交叉弹性没有效用基础。McFadden：随机效用 \\(u_{ij}=x_{ij}\\beta+\\varepsilon_{ij}\\)，\\(\\varepsilon\\) 若 i.i.d. 第一类极值，则</p> \\[P_{ij}=\\frac{\\exp(x_{ij}\\beta)}{\\sum_k\\exp(x_{ik}\\beta)}. \\]<p>缺口不是再讲劳动供给从哪来，而是：这套概率从效用来，反事实（关一条公交线、涨一种票价）是改 \\(x\\) 再算份额——结构的第一次落地。Probit 用正态 \\(\\varepsilon\\)，无闭式，要积分；二元时两者相似，多元 probit 允许相关误差，计算重。</p><p><span class="marginnote">IIA：任意两选项的概率比不依赖第三选项。红蓝公交悖论：加一辆涂成红色的车，logit 从蓝车偷来的份额与从汽车偷来的成比例，往往不像话。嵌套 logit、随机系数下一课 BLP 正是冲这个来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>条件 logit 的似然是观测选择的 \\(\\sum\\log P_{i,y_i}\\)。识别：只识别效用差，水平不定；一个选项的常数要归一。只随人变的 \\(z_i\\) 必须与选项交互才能进模型。内生价格：\\(x\\) 含 \\(p\\) 且 \\(p\\) 与 \\(\\varepsilon\\) 相关（未观测质量），logit 的 \\(\\beta_p\\) 有偏——下一课 BLP 的矩。本课先假设 \\(x\\) 外生，把装置钉清。</p>',10)),(i(),n(c,null,{default:t(()=>[d(o,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E9%9A%8F%E6%9C%BA%E6%95%88%E7%94%A8%22%5D%20--%3E%20MAX%5B%22%E9%80%89%E6%95%88%E7%94%A8%E6%9C%80%E5%A4%A7%E9%A1%B9%22%5D%0A%20%20EV%5B%22i.i.d.%20%E6%9E%81%E5%80%BC%22%5D%20--%3E%20LOGIT%5B%22%E9%97%AD%E5%BC%8F%E4%BB%BD%E9%A2%9D%22%5D%0A%20%20LOGIT%20--%3E%20IIA%5B%22IIA%3A%20%E7%9B%B8%E5%AF%B9%E4%BB%BD%E9%A2%9D%E9%92%89%E6%AD%BB%22%5D%0A%20%20NEST%5B%22%E5%B5%8C%E5%A5%97%20%2F%20%E9%9A%8F%E6%9C%BA%E7%B3%BB%E6%95%B0%22%5D%20--%3E%20FLEX%5B%22%E6%9B%BF%E4%BB%A3%E6%A8%A1%E5%BC%8F%E7%81%B5%E6%B4%BB%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>劳动参与二元 probit 与<a href="/econ/labor-participation">选择</a>理论课对接：这里估的是参与方程，不重写家庭劳动–闲暇的一阶条件全文。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是比较。确定性效用差越大，选择概率越极端。极值误差给出 logit 的厚尾；正态给出更薄的尾。福利：logsum（期望最大效用）是 McFadden 的消费者剩余，反事实关选项等于从 logsum 里拿掉一项。这是结构福利，不是 DiD 的 ATT。IIA 失败时 logsum 的替代模式错，福利跟着错。</p><p>与潜在结果：离散选择给的是每人对每个 \\(j\\) 的潜在效用，观测只看见 argmax。ATE 语言要定义处理（例如关选项 \\(j\\)）再积分概率差。两者可对译，logit 额外给出未选选项的反事实份额。</p><p><span class="marginnote">Train 的模拟：混合 logit 用随机系数对 IIA 松绑，似然无闭式，用 GHK 或混合频率模拟。计算是方法，识别仍靠效用差的变异。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估 BLP 的供给边。不把 logit 当所有离散决策的真误差。动态离散选择（Rust 引擎、Hotz–Miller）是另一课量级，本课只标：一旦有续值，静态 logit 把续值吞进误差，政策反事实会错。下一课价格内生与市场均衡。</p><p>后课默认：外生 \\(x\\) 下条件 logit 给出份额与 logsum；IIA 是实质性限制。内生价格与差异产品市场交给 BLP。不要用线性概率的系数当结构弹性去改从未出现的选项集。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>随机效用 + 极值误差 ⇒ 条件 logit 份额。</li><li>只识别效用差；IIA 限制替代模式。</li><li>反事实改 \\(x\\) 或选项集，再算份额与 logsum。</li><li>内生价格本课不处理，留给 BLP。</li><li>出处：McFadden 1974；Train, <em>Discrete Choice Methods with Simulation</em>。</li></ul>',10))])}const T=l(B,[["render",h]]);export{b as __pageData,T as default};
